package org.efootballrevival.runtimeprobe;
import android.app.*;import android.content.*;import android.text.InputType;import android.widget.*;import org.json.*;
public final class StatEditor {
 private static String manage(Activity a,String action,JSONObject req)throws Exception{return(String)Class.forName("org.efootballrevival/runtimeprobe/EmbeddedGateway".replace('/','.')).getMethod("manage",Context.class,String.class,String.class).invoke(null,a,action,req.toString());}
 private static void error(Activity a,Exception e){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("Player Attributes").setMessage(String.valueOf(e.getCause()==null?e:e.getCause())).setPositiveButton("Close",null).show();}
 public static void attach(Activity a,LinearLayout box,JSONObject player){Button b=new Button(a);b.setAllCaps(false);b.setText("Player Attributes · Min0 / Max127");box.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->{b.setEnabled(false);new Thread(()->{try{JSONObject data=new JSONObject(manage(a,"ui712_stats_get",player));a.runOnUiThread(()->{b.setEnabled(true);if(!a.isFinishing())form(a,player,data);});}catch(Exception e){a.runOnUiThread(()->{b.setEnabled(true);error(a,e);});}},"AttributesLoad").start();});}
 private static void form(Activity a,JSONObject player,JSONObject data){try{LinearLayout box=new LinearLayout(a);box.setOrientation(1);int pad=Math.round(16*a.getResources().getDisplayMetrics().density);box.setPadding(pad,pad,pad,pad);ScrollView scroll=new ScrollView(a);scroll.addView(box);TextView note=new TextView(a);note.setText("Native storage range:0–127. Gameplay may impose a lower effective cap.128 wraps to0 and cannot be saved. Save before Enter Game; reopen the app afterwards.");box.addView(note);JSONArray fields=data.getJSONArray("fields");JSONObject current=data.getJSONObject("values");EditText[] edits=new EditText[fields.length()];
 for(int i=0;i<edits.length;i++){JSONObject f=fields.getJSONObject(i);TextView t=new TextView(a);t.setText(f.getString("name")+" · Min0 / Max127");box.addView(t);EditText n=new EditText(a);n.setSingleLine(true);n.setInputType(InputType.TYPE_CLASS_NUMBER);n.setText(String.valueOf(current.getInt(String.valueOf(f.getInt("index")))));box.addView(n,new LinearLayout.LayoutParams(-1,-2));edits[i]=n;}
 AlertDialog d=new AlertDialog.Builder(a).setTitle("Player Attributes").setView(scroll).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();d.show();ResponsiveUi.fit(a,d);d.getButton(-1).setOnClickListener(v->{try{JSONObject values=new JSONObject();for(int i=0;i<edits.length;i++){int n=Integer.parseInt(edits[i].getText().toString());if(n<0||n>127){edits[i].setError("Min0 / Max127");edits[i].requestFocus();return;}values.put(String.valueOf(fields.getJSONObject(i).getInt("index")),n);}JSONObject req=new JSONObject(player.toString()).put("values",values);d.getButton(-1).setEnabled(false);new Thread(()->{try{JSONObject out=new JSONObject(manage(a,"ui712_stats_apply",req));if(!out.optBoolean("saved"))throw new Exception("Save not confirmed");a.runOnUiThread(()->{d.dismiss();Toast.makeText(a,"Saved. Reopen the app.",Toast.LENGTH_LONG).show();});}catch(Exception e){a.runOnUiThread(()->{d.getButton(-1).setEnabled(true);error(a,e);});}},"AttributesSave").start();}catch(Exception e){error(a,e);}});
 }catch(Exception e){error(a,e);}}
}
